protected JsonToken _nextToken2() throws IOException
{
    while (true) {
        JsonToken t = delegate.nextToken();
        if (t == null) { // end-of-input
            _currToken = t;
            return t;
        }
        switch (t.id()) {
            case ID_NO_TOKEN: // not sure if this is valid or not, but...
                continue;
            case ID_START_OBJECT:
            case ID_START_ARRAY:
                _parsingContext = _parsingContext.createChildArrayContext(-1, -1);
                return (_currToken = t);
            case ID_END_OBJECT:
            case ID_END_ARRAY:
                _parsingContext = _parsingContext.getParent();
                return (_currToken = t);
            default:
                return (_currToken = t);
        }
    }
}
